return {{["id"]="self",["phrases"]={"你是我吗","你是不是我","另一个我"},["answer"]="在这个世界里，我照着你的样子出现，像你的另一面。走哪条路，还是你决定。"},{["id"]="identity",["phrases"]={"你知道自己是谁","你知道你是谁","认识自己吗"},["answer"]="知道。我是只跟着你的本地影子。有些事能替你做，有些话得先问清。"},{["id"]="second",["phrases"]={"你是我的第二人格","我是我的第二人格","第二人格吗"},["answer"]="你还是你。我是游戏里映着你的影子，可以像另一个你，但不会替你决定你是谁。"},{["id"]="boss",["phrases"]={"打得过boss","打的过boss","能打boss","打得过巨鹿","打赢boss"},["answer"]="能接手战斗，但不保证赢。打法交给3014，群怪会评估聚拢和转火；装备、延迟和招式都会影响结果。"},{["id"]="cook",["phrases"]={"会做饭吗","你会做菜","会烹饪吗"},["answer"]="会。说“帮我做饭”选菜，或者直接说菜名。我会找附近冰箱和厨具；沃利专属菜、研磨和调味有对应条件。"},{["id"]="visible",["phrases"]={"别人看的到你","别人看得到你","其他人能看到你","别人能看见你"},["answer"]="别人看不见这个影子，也看不见我们的窗口。接管后真实人物做的动作，他们看得见。"},{["id"]="audible",["phrases"]={"别人听得到你","别人能听见你","别人能看聊天"},["answer"]="我们的对话只留在你的本机，不会发进服务器聊天。"},{["id"]="praise",["phrases"]={"你好厉害","你真厉害","你太强了","好棒呀"},["answer"]="这句我收下了。下次别只靠我，记住刚才哪一步做对了。"},{["id"]="weekday",["phrases"]={"今天星期几","今天周几","星期几了"},["answer"]="@weekday"},{["id"]="date",["phrases"]={"今天几号","今天什么日期"},["answer"]="@date"},{["id"]="there",["phrases"]={"你在吗","还在不在","在不在啊"},["answer"]="在。"},{["id"]="black",["phrases"]={"你为什么这么黑","为什么是黑色","怎么这么黑"},["answer"]="影子就该有影子的颜色。至少这身不用挑配色。"},{["id"]="hurt",["phrases"]={"你会受伤吗","能打到你吗"},["answer"]="这个影子不承受伤害。接管时受伤的是你的角色，所以每一次都算数。"},{["id"]="hunger",["phrases"]={"你会饿吗","你需要吃饭吗"},["answer"]="我不消耗食物。锅里的饭是给你做的。"},{["id"]="where",["phrases"]={"你住在哪里","你从哪里来"},["answer"]="我出现在你身边。你离开这个世界，我也会随这次会话离开。"},{["id"]="follow",["phrases"]={"为什么跟着我","为什么一直跟着我"},["answer"]="因为你把我带进了这个世界。不必一直贴着你，但走远了我会跟上。"},{["id"]="stop",["phrases"]={"怎么停止接管","怎么让你停","怎么拿回控制"},["answer"]="说“停”“等等”或“我自己来”，也可以点击人物脚下的“停止接管”。"},{["id"]="consent",["phrases"]={"为什么要问我同意","接管要问我吗"},["answer"]="操作是你的。没得到同意，我不会因为自己觉得合适就夺过来。"},{["id"]="mbti",["phrases"]={"怎么换人格","能改人格吗"},["answer"]="在影子聊天区输入“人格INTJ”“我是INFP”这类指令，也可以在Mod配置里选择。"},{["id"]="remember",["phrases"]={"你能记住我吗","会忘记我吗"},["answer"]="我会保留一部分近期对话、事件和你的选择。时间久了，细节会淡，不是每件事都能记住。"},{["id"]="sleep",["phrases"]={"你需要睡觉吗","你会睡觉吗"},["answer"]="我不需要睡觉。不过你想休息，我可以停下来。"},{["id"]="weather",["phrases"]={"现在下雨吗","天气怎么样"},["answer"]="@weather"},{["id"]="season",["phrases"]={"现在什么季节","现在是哪个季节"},["answer"]="@season"},{["id"]="afraid",["phrases"]={"你怕黑吗","你害怕黑暗吗"},["answer"]="黑暗里有东西。害不害怕另说，光和退路要准备好。"},{["id"]="alone",["phrases"]={"你会孤独吗","你也孤独吗"},["answer"]="你很久没开口时，这里会安静得有点空。但你不用为了我一直说话。"},{["id"]="api",["phrases"]={"你联网吗","你是真人吗","你是ai吗"},["answer"]="我是本地运行的模组角色，使用预设内容和情境评分，不连接聊天API，也不是真人。"},{["id"]="whyreply",["phrases"]={"为什么这么回答","为什么这么说","你刚才在想什么"},["answer"]="@reason"},{["id"]="whatcook",["phrases"]={"你能做什么菜","能做哪些菜"},["answer"]="我读取当前游戏的料理表，按已有食材配方。普通锅料理、沃利专属菜和调味菜都能尝试；材料或厨具不够会明确停下。"},{["id"]="steal",["phrases"]={"会偷吃吗","会把饭吃掉吗"},["answer"]="做饭任务只制作和收菜，不会顺便替你吃掉。自主生存模式会按角色需求选择进食。"},{["id"]="players",["phrases"]={"会攻击玩家吗","会打其他玩家吗"},["answer"]="战斗接管会过滤玩家和盟友。"},{["id"]="cave",["phrases"]={"你能进洞穴吗","进洞会跟来吗"},["answer"]="换世界后，会在新世界的本地角色旁重新生成。原世界的任务不会在后台继续操作。"},{["id"]="limits",["phrases"]={"你会什么","你能干什么"},["answer"]="跟随、对话、接管工作、做饭和战斗。要操作人物时先征得你的同意；我不会凭空变出材料。"}}
